group_label":"Faux plafond SDB","source_column":"R","sort_order":13},{"code":"ceiling-hvac","label":"Réseaux clim / ventilation","zone":"bathroom","group_label":"Faux plafond SDB","source_column":"S","sort_order":14},{"code":"access-panel-approved","label":"Trappe de visite","zone":"bathroom","group_label":"Faux plafond SDB","source_column":"T","sort_order":15},{"code":"ceiling-close-clearance","label":"Bon à fermer faux plafond","zone":"bathroom","group_label":"Faux plafond SDB","source_column":"U","sort_order":16},{"code":"ceiling-close","label":"Fermeture faux plafond","zone":"bathroom","group_label":"Faux plafond SDB","source_column":"V","sort_order":17},{"code":"ceiling-finish","label":"Finition faux plafond","zone":"bathroom","group_label":"Faux plafond SDB","source_column":"W","sort_order":18},{"code":"ceiling-paint","label":"Peinture faux plafond","zone":"bathroom","group_label":"Peinture FP","source_column":"X","sort_order":19},{"code":"wall-covering","label":"Pose revêtement toilette","zone":"bathroom","group_label":"Revêtement mural","source_column":"Y","sort_order":20},{"code":"shower-wall-covering","label":"Pose revêtement douche","zone":"bathroom","group_label":"Revêtement mural","source_column":"Z","sort_order":21},{"code":"floor-covering","label":"Pose revêtement sol","zone":"bathroom","group_label":"Revêtement sol","source_column":"AA","sort_order":22},{"code":"aluminium","label":"Faux cadres alu","zone":"bathroom","group_label":"Menuiserie alu","source_column":"AB","sort_order":23},{"code":"shower-toilet-frames","label":"Pose châssis / cabine douche / cabine WC","zone":"bathroom","group_label":"Menuiserie alu","source_column":"AC","sort_order":24},{"code":"woodwork","label":"Rail porte coulissante","zone":"bathroom","group_label":"Menuiserie bois","source_column":"AD","sort_order":25},{"code":"sliding-door-partition-close","label":"Fermeture cloison porte coulissante","zone":"bathroom","group_label":"Menuiserie bois","source_column":"AE","sort_orde